<?php

declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT p.*,e.allow_download,e.is_active FROM photos p JOIN events e ON e.id=p.event_id WHERE p.id=? AND p.is_visible=1 LIMIT 1');$s->execute([$id]);$p=$s->fetch();if(!$p||!$p['allow_download']||!$p['is_active']){http_response_code(404);exit('ไม่พบรูปหรือไม่ได้รับอนุญาต');}$root=realpath(STORAGE_PATH);$file=realpath(__DIR__.'/'.$p['local_path']);if(!$root||!$file||!str_starts_with($file,$root.DIRECTORY_SEPARATOR)||!is_file($file)){http_response_code(404);exit('ไม่พบไฟล์');}db()->prepare('INSERT INTO download_logs(photo_id,ip_hash,created_at) VALUES(?,?,NOW())')->execute([(int)$p['id'],hash('sha256',(string)($_SERVER['REMOTE_ADDR']??''))]);header('Content-Type: '.$p['mime_type']);header('Content-Length: '.filesize($file));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($p['file_name']));header('X-Content-Type-Options: nosniff');readfile($file);
